export type LearningEvent = { id: string; lessonId: string; kind: string; at: string };
export type LearningState = { practiced: boolean };
export type LearningGroup = { id: string; title: string; ids: string[]; href: string };

const berlinDay = (value: Date) => new Intl.DateTimeFormat("sv-SE", {
  timeZone: "Europe/Berlin", year: "numeric", month: "2-digit", day: "2-digit",
}).format(value);

// Events come from the validated, append-only shared store. Reopening a lesson
// changes its current completion, while preserving the earlier achievement.
export function learningProgressChart(
  states: Record<string, LearningState>, events: LearningEvent[],
  groups: LearningGroup[], now = new Date(),
) {
  const ids = new Set(groups.flatMap(group => group.ids));
  const tracks = groups.map(group => ({ ...group, total: group.ids.length,
    completed: group.ids.filter(id => states[id]?.practiced === true).length }));
  const completed = [...ids].filter(id => states[id]?.practiced === true).length;
  const today = berlinDay(now);
  const todayUtc = Date.parse(today + "T12:00:00Z");
  const dayKeys = Array.from({ length: 14 }, (_, i) =>
    new Date(todayUtc - (13 - i) * 86400000).toISOString().slice(0, 10));
  const seen = new Set<string>();
  const ordered = events.filter(event => {
    if (seen.has(event.id) || !ids.has(event.lessonId) || !Number.isFinite(Date.parse(event.at)) || Date.parse(event.at) > now.getTime()) return false;
    seen.add(event.id); return true;
  }).sort((a, b) => a.at.localeCompare(b.at) || a.id.localeCompare(b.id))
    .map(event => ({ ...event, day: berlinDay(new Date(event.at)) }));
  const practiced = new Set<string>();
  let cursor = 0;
  const history = dayKeys.map(day => {
    while (cursor < ordered.length && ordered[cursor].day <= day) {
      const event = ordered[cursor++];
      if (event.kind === "practice" || event.kind === "mastery") practiced.add(event.lessonId);
      if (event.kind === "reopen") practiced.delete(event.lessonId);
    }
    return { day, completed: practiced.size };
  });
  const achievedIds = new Set(ordered.filter(event => event.kind === "practice" || event.kind === "mastery").map(event => event.lessonId));
  const last = ordered.filter(event => event.kind === "practice" || event.kind === "mastery").at(-1);
  return { tracks, completed, total: ids.size,
    percent: ids.size ? Math.round(completed / ids.size * 100) : 0,
    history, lastPractice: last?.day ?? null, hasPracticeHistory: achievedIds.size > 0 };
}
